# Fourier & Laplace Transforms · 1-сабақ: Фурье қатарлары
from math_lesson_gen import L, D, T, F, REM, ATT, NOTE, P_, X


def _partial(term, ks):
    """graph визуализациясы үшін: N слайдері k ≤ N мүшелерін «қосады» (sign арқылы, салыстырусыз)."""
    return " + ".join(f"({term.format(k=k)})*(sign(N-{k}+0.5)+1)/2" for k in ks)


SQUARE = _partial("4/(pi*{k})*sin({k}*x)", range(1, 30, 2))
SAW = _partial("2*(-1)^({k}+1)/{k}*sin({k}*x)", range(1, 16))

